export function t(language: Language, key: string): string {
  return siteText(language, key) ?? extraTranslations[language][key] ?? dictionaries[language][key] ?? dictionaries.en[key] ?? key;
}

export function detectLanguage(): Language {
  try {
    const saved = localStorage.getItem("meridian-language");
    if (saved === "en" || saved === "ar" || saved === "ms" || saved === "zh") return saved;
  } catch { /* private browsing may disable storage */ }
  const locale = navigator.language.toLowerCase();
  if (locale.startsWith("en")) return "en";
  if (locale.startsWith("ms") || locale.startsWith("ma")) return "ms";
  if (locale.startsWith("zh")) return "zh";
  return "ar";
}
